export const PAGE = "<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Auvra Ads Mirror</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Inter+Tight:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap\">\n<style>\n  /* Ads Manager-style workspace: a control bar, level tabs, then one dense, sortable table with a totals row. */\n  :root { --bg:#f4f5f7; --panel:#fff; --ink:#1c1e21; --muted:#65676b; --line:#e4e6eb; --accent:#1660d6; --accent-soft:#e7f0fd;\n    --ok:#1b8a4b; --warn:#b26a00; --bad:#c2282f; --chip:#f0f2f5; --sans:\"Inter Tight\",system-ui,-apple-system,\"Segoe UI\",sans-serif; --mono:\"JetBrains Mono\",ui-monospace,Menlo,monospace; }\n  @media (prefers-color-scheme: dark) { :root { --bg:#0f1115; --panel:#181b21; --ink:#e7e9ee; --muted:#9aa1ad; --line:#2a2f38; --accent:#5c9bff; --accent-soft:#1b2a44;\n    --ok:#4cc38a; --warn:#e3a33b; --bad:#ff6b6b; --chip:#232831; color-scheme: dark; } }\n  * { box-sizing: border-box; }\n  [hidden] { display: none !important; }\n  body { margin:0; background:var(--bg); color:var(--ink); font:14px/1.45 var(--sans); }\n  .wrap { padding: 16px max(16px, env(safe-area-inset-left)) 40px max(16px, env(safe-area-inset-right)); display:grid; gap:12px; }\n  header { display:flex; flex-wrap:wrap; align-items:center; justify-content:space-between; gap:8px 16px; }\n  h1 { margin:0; font-size:18px; font-weight:700; letter-spacing:-.01em; }\n  h1 span { color:var(--muted); font-weight:500; }\n  .live { display:flex; align-items:center; gap:8px; color:var(--muted); font-size:13px; }\n  .dot { width:8px; height:8px; border-radius:50%; background:var(--ok); box-shadow:0 0 0 3px color-mix(in srgb, var(--ok) 25%, transparent); }\n  .dot.stale { background:var(--warn); } .dot.err { background:var(--bad); }\n  button, select, input { font:inherit; color:inherit; }\n  .btn { border:1px solid var(--line); background:var(--panel); border-radius:6px; padding:6px 12px; cursor:pointer; font-weight:500; }\n  .btn:hover { border-color:var(--accent); }\n  a.btn { color:inherit; text-decoration:none; display:inline-block; }\n  .bar { background:var(--panel); border:1px solid var(--line); border-radius:8px; padding:10px 12px; display:flex; flex-wrap:wrap; gap:8px; align-items:center; }\n  .bar select, .bar input { border:1px solid var(--line); background:var(--panel); border-radius:6px; padding:6px 8px; min-width:0; }\n  .bar input[type=search] { flex:1 1 220px; }\n  .bar label { font-size:12px; color:var(--muted); display:grid; gap:2px; }\n  .tabs { display:flex; gap:2px; border-bottom:1px solid var(--line); overflow-x:auto; }\n  .tabs button { border:0; background:none; padding:8px 14px; cursor:pointer; color:var(--muted); font-weight:600; border-bottom:2px solid transparent; white-space:nowrap; }\n  .tabs button[aria-selected=true] { color:var(--accent); border-color:var(--accent); }\n  .cols { position:relative; }\n  .colmenu { position:absolute; right:0; top:calc(100% + 4px); z-index:5; background:var(--panel); border:1px solid var(--line); border-radius:8px; padding:8px; display:grid; grid-template-columns:repeat(2, minmax(150px,1fr)); gap:2px 12px; box-shadow:0 8px 24px rgb(0 0 0 / .12); width:min(92vw, 380px); }\n  .colmenu label { display:flex; gap:6px; align-items:center; font-size:13px; padding:3px 0; cursor:pointer; }\n  .tablebox { background:var(--panel); border:1px solid var(--line); border-radius:8px; overflow:auto; max-height:calc(100vh - 240px); }\n  table { border-collapse:separate; border-spacing:0; width:100%; font-variant-numeric:tabular-nums; }\n  th, td { padding:8px 10px; border-bottom:1px solid var(--line); text-align:right; white-space:nowrap; }\n  th { position:sticky; top:0; z-index:2; background:var(--panel); font-size:12px; color:var(--muted); font-weight:600; cursor:pointer; user-select:none; }\n  th[aria-sort=ascending]::after { content:\" ▲\"; } th[aria-sort=descending]::after { content:\" ▼\"; }\n  th.name, td.name { text-align:left; position:sticky; left:0; background:var(--panel); z-index:1; min-width:280px; max-width:420px; white-space:normal; }\n  th.name { z-index:3; }\n  tr.total td { font-weight:600; background:var(--chip); position:sticky; top:33px; z-index:2; }\n  tr.total td.name { background:var(--chip); }\n  tr.group td { background:var(--accent-soft); font-weight:600; }\n  tr.group td.name { background:var(--accent-soft); }\n  .item { display:grid; grid-template-columns:40px 1fr; gap:10px; align-items:center; }\n  .thumb { width:40px; height:40px; border-radius:6px; object-fit:cover; background:var(--chip); }\n  .rname { font-weight:500; overflow-wrap:anywhere; font-size:13px; }\n  .sub { font-size:12px; color:var(--muted); overflow-wrap:anywhere; }\n  .sub a { color:var(--accent); text-decoration:none; } .sub a:hover { text-decoration:underline; }\n  .chip { display:inline-block; font-size:11px; font-weight:600; padding:1px 7px; border-radius:99px; background:var(--chip); color:var(--muted); margin-right:6px; vertical-align:1px; }\n  .chip.ACTIVE { color:var(--ok); background:color-mix(in srgb, var(--ok) 14%, transparent); }\n  .chip.DISAPPROVED, .chip.WITH_ISSUES { color:var(--bad); background:color-mix(in srgb, var(--bad) 14%, transparent); }\n  .chip.IN_PROCESS, .chip.PENDING_REVIEW, .chip.PREAPPROVED { color:var(--warn); background:color-mix(in srgb, var(--warn) 16%, transparent); }\n  .note { color:var(--muted); font-size:12px; margin:0; }\n  .preview-note { flex-basis:100%; margin:0; font-size:13px; color:var(--warn); }\n  #asViewer[aria-pressed=true] { border-color:var(--warn); color:var(--warn); }\n  .drill { all:unset; cursor:pointer; color:var(--accent); font-weight:600; overflow-wrap:anywhere; }\n  .drill:hover { text-decoration:underline; }\n  tr.slice td { color:var(--muted); font-size:12.5px; }\n  tr.slice td.name { padding-left:58px; }\n  .msg { padding:24px; text-align:center; color:var(--muted); }\n  .err { color:var(--bad); }\n  :focus-visible { outline:2px solid var(--accent); outline-offset:1px; }\n  @media (max-width:700px) { th.name, td.name { min-width:200px; } }\n</style></head>\n<body><div class=\"wrap\">\n  <header>\n    <h1>Auvra Ads Mirror <span id=\"who\">· viewing as __WHO__</span></h1>\n    <p class=\"preview-note\" id=\"previewNote\" hidden>You're seeing the page exactly as an invited strategist does: your columns, no column controls, no Strategist filter, no Export CSV.</p>\n    <div class=\"live\"><a class=\"btn\" id=\"access\" href=\"#\" target=\"_blank\" rel=\"noopener\" hidden>Manage access</a><button class=\"btn\" id=\"asViewer\" type=\"button\" hidden aria-pressed=\"false\">View as strategist</button><i class=\"dot\" id=\"dot\"></i><span id=\"updated\">Loading…</span><button class=\"btn\" id=\"refresh\" type=\"button\">Refresh</button></div>\n  </header>\n\n  <div class=\"bar\">\n    <label>Date range<select id=\"preset\">\n      <option value=\"today\">Today</option><option value=\"yesterday\">Yesterday</option><option value=\"last_3d\">Last 3 days</option>\n      <option value=\"last_7d\" selected>Last 7 days</option><option value=\"last_14d\">Last 14 days</option><option value=\"last_30d\">Last 30 days</option>\n      <option value=\"this_month\">This month</option><option value=\"last_month\">Last month</option><option value=\"maximum\">Maximum</option><option value=\"custom\">Custom…</option></select></label>\n    <label id=\"sinceL\" hidden>From<input type=\"date\" id=\"since\"></label>\n    <label id=\"untilL\" hidden>To<input type=\"date\" id=\"until\"></label>\n    <label id=\"csL\" hidden>Strategist<select id=\"cs\"><option value=\"\">All strategists</option></select></label>\n    <label>Campaign<select id=\"campaign\"><option value=\"\">All campaigns</option></select></label>\n    <label>Ad set<select id=\"adset\"><option value=\"\">All ad sets</option></select></label>\n    <label>Delivery<select id=\"status\"><option value=\"\">All</option><option value=\"ACTIVE\">Active</option><option value=\"REVIEW\">In review</option><option value=\"REJECTED\">Rejected / issues</option><option value=\"OFF\">Off</option></select></label>\n    <input type=\"search\" id=\"q\" placeholder=\"Search by name…\" aria-label=\"Search by name\">\n    <label id=\"colsL\">Columns<select id=\"preset-cols\"><option value=\"performance\">Performance</option><option value=\"delivery\">Delivery</option><option value=\"engagement\">Engagement</option>\n      <option value=\"video\">Video engagement</option><option value=\"conversions\">Conversions</option><option value=\"custom\">Custom</option></select></label>\n    <label>Breakdown<select id=\"breakdown\"><option value=\"\">None</option><option value=\"age\">Age</option><option value=\"gender\">Gender</option>\n      <option value=\"platform\">Platform</option><option value=\"placement\">Placement</option><option value=\"device\">Impression device</option></select></label>\n    <div class=\"cols\"><button class=\"btn\" id=\"colsBtn\" type=\"button\" aria-expanded=\"false\">Customize columns</button><div class=\"colmenu\" id=\"colmenu\" hidden></div></div>\n    <button class=\"btn\" id=\"export\" type=\"button\" hidden>Export CSV</button>\n  </div>\n  \n  <div class=\"tabs\" role=\"tablist\">\n    <button role=\"tab\" data-level=\"ad\" aria-selected=\"true\">Ads</button>\n    <button role=\"tab\" data-level=\"adset\" aria-selected=\"false\">Ad sets</button>\n    <button role=\"tab\" data-level=\"campaign\" aria-selected=\"false\">Campaigns</button>\n    <button role=\"tab\" data-level=\"hook\" aria-selected=\"false\">Hooks (H1/H2/H3)</button>\n  </div>\n\n  <div class=\"tablebox\"><table><thead><tr id=\"head\"></tr></thead><tbody id=\"body\"><tr><td class=\"msg\" colspan=\"20\">Loading live data from Meta…</td></tr></tbody></table></div>\n  <p class=\"note\">Live from Meta: refreshes every 2 minutes (Meta's own numbers can lag a few minutes). Hook rate = 3-second video views ÷ impressions. Hold rate = ThruPlays ÷ 3-second views. CTR and CPC use link clicks. Read-only: changes are made in Ads Manager.</p>\n</div>\n<script>\nconst $ = (id) => document.getElementById(id);\nconst COLS = [\n  [\"spend\",\"Amount spent\",\"$\"],[\"impressions\",\"Impressions\",\"n\"],[\"reach\",\"Reach\",\"n\"],[\"frequency\",\"Frequency\",\"f\"],[\"cpm\",\"CPM\",\"$\"],\n  [\"link_clicks\",\"Link clicks\",\"n\"],[\"ctr\",\"CTR (link)\",\"%\"],[\"cpc\",\"CPC (link)\",\"$\"],[\"lpv\",\"Landing page views\",\"n\"],[\"atc\",\"Adds to cart\",\"n\"],\n  [\"cost_atc\",\"Cost per add to cart\",\"$\"],[\"checkouts\",\"Checkouts initiated\",\"n\"],[\"purchases\",\"Purchases\",\"n\"],[\"cpa\",\"Cost per purchase\",\"$\"],\n  [\"revenue\",\"Purchase value\",\"$\"],[\"roas\",\"ROAS\",\"x\"],[\"video3s\",\"3-second video plays\",\"n\"],[\"thruplay\",\"ThruPlays\",\"n\"],\n  [\"hook\",\"Hook rate\",\"%\"],[\"hold\",\"Hold rate\",\"%\"]];\n// Ads Manager's column presets.\nconst PRESET_COLS = {\n  performance: [\"spend\",\"impressions\",\"cpm\",\"ctr\",\"cpc\",\"atc\",\"purchases\",\"cpa\",\"roas\",\"hook\",\"hold\"],\n  delivery: [\"spend\",\"reach\",\"impressions\",\"frequency\",\"cpm\"],\n  engagement: [\"spend\",\"impressions\",\"link_clicks\",\"ctr\",\"cpc\",\"lpv\"],\n  video: [\"spend\",\"impressions\",\"video3s\",\"thruplay\",\"hook\",\"hold\",\"cpm\"],\n  conversions: [\"spend\",\"lpv\",\"atc\",\"cost_atc\",\"checkouts\",\"purchases\",\"cpa\",\"revenue\",\"roas\"] };\nconst DEFAULT = PRESET_COLS.performance;\nlet shown, preset = \"performance\";\ntry { preset = localStorage.getItem(\"mirror-preset\") || \"performance\"; shown = preset === \"custom\" ? JSON.parse(localStorage.getItem(\"mirror-cols\")) || DEFAULT : PRESET_COLS[preset]; } catch { shown = DEFAULT; }\nlet viewerPreview = false;\nlet data = null, level = \"ad\", sort = { key: \"spend\", dir: -1 }, timer = null, bd = null, pick = null, drilled = false;   // pick = ad ids from a Hooks click\nconst fmt = { \"$\": (v) => v == null ? \"—\" : \"$\" + v.toLocaleString(\"en-US\", { minimumFractionDigits: 2, maximumFractionDigits: 2 }),\n  n: (v) => v == null ? \"—\" : Math.round(v).toLocaleString(\"en-US\"), f: (v) => v == null ? \"—\" : v.toFixed(2),\n  \"%\": (v) => v == null ? \"—\" : (v * 100).toFixed(2) + \"%\", x: (v) => v == null ? \"—\" : v.toFixed(2) };\nconst SUMS = [\"spend\",\"impressions\",\"reach\",\"link_clicks\",\"lpv\",\"atc\",\"checkouts\",\"purchases\",\"revenue\",\"video3s\",\"thruplay\"];\nfunction derive(r) {\n  const d = (a, b) => (b ? a / b : null);\n  return { ...r, cpm: d(r.spend * 1000, r.impressions), ctr: d(r.link_clicks, r.impressions), cpc: d(r.spend, r.link_clicks), cost_atc: d(r.spend, r.atc),\n    cpa: d(r.spend, r.purchases), roas: d(r.revenue, r.spend), hook: d(r.video3s, r.impressions), hold: d(r.thruplay, r.video3s),\n    frequency: r.reach ? r.impressions / r.reach : null,\n    ...Object.fromEntries(Object.keys(r).filter((k) => k.startsWith(\"cc_\")).map((k) => [\"ccc_\" + k.slice(3), d(r.spend, r[k])])) };\n}\n// Custom conversions from Meta become columns on their own: count, cost per, and value.\nfunction allCols() {\n  const cc = (data && data.customConversions) || [];\n  return [...COLS, ...cc.flatMap((c) => [[\"cc_\" + c.id, c.name, \"n\"], [\"ccc_\" + c.id, \"Cost per \" + c.name, \"$\"], [\"ccv_\" + c.id, c.name + \" value\", \"$\"]])];\n}\nconst visible = () => { const all = new Map(allCols().map((c) => [c[0], c])); return shown.map((k) => all.get(k)).filter(Boolean); };\nfunction sum(rows, extra) {\n  const t = { ...extra }, keys = new Set(SUMS);\n  for (const r of rows) for (const k in r) if (k.startsWith(\"cc_\") || k.startsWith(\"ccv_\")) keys.add(k);\n  for (const k of keys) t[k] = rows.reduce((s, r) => s + (r[k] || 0), 0);\n  return derive(t);\n}\nfunction ownerOf(r) {\n  const S = data.strategists || {}, up = (s) => (s || \"\").toUpperCase();\n  for (const [cs, rule] of Object.entries(S)) if ((rule.ad || []).some((p) => up(r.name).startsWith(up(p))) || (rule.adset || []).some((p) => up(r.adset).startsWith(up(p)))) return cs;\n  return \"Other\";\n}\nconst deliv = (s) => s === \"ACTIVE\" ? \"ACTIVE\" : [\"IN_PROCESS\",\"PENDING_REVIEW\",\"PREAPPROVED\"].includes(s) ? \"REVIEW\" : [\"DISAPPROVED\",\"WITH_ISSUES\"].includes(s) ? \"REJECTED\" : \"OFF\";\nconst LABEL = { ACTIVE: \"Active\", IN_PROCESS: \"In review\", PENDING_REVIEW: \"In review\", PREAPPROVED: \"In review\", DISAPPROVED: \"Rejected\", WITH_ISSUES: \"Issue\", OFF: \"Off\" };\nfunction filtered() {\n  const q = $(\"q\").value.trim().toLowerCase(), cs = $(\"cs\").value, c = $(\"campaign\").value, a = $(\"adset\").value, st = $(\"status\").value;\n  const only = pick && new Set(pick.ids);\n  return data.rows.filter((r) => (!only || only.has(r.id)) && (!cs || r._cs === cs) && (!c || r.campaign === c) && (!a || r.adset === a) && (!st || deliv(r.status) === st)\n    && (!q || (r.name + \" \" + r.adset + \" \" + r.campaign).toLowerCase().includes(q)));\n}\nfunction fillSelect(id, values, keep) {\n  const el = $(id), cur = el.value, first = el.options[0];\n  el.replaceChildren(first, ...[...new Set(values)].filter(Boolean).sort().map((v) => new Option(v, v)));\n  el.value = [...el.options].some((o) => o.value === cur) ? cur : \"\";\n}\nfunction cell(tag, text, cls) { const e = document.createElement(tag); if (cls) e.className = cls; e.textContent = text; return e; }\nfunction nameCell(r, kind) {\n  const td = document.createElement(\"td\"); td.className = \"name\";\n  if (kind === \"ad\") {\n    const box = document.createElement(\"div\"); box.className = \"item\";\n    const img = document.createElement(\"img\"); img.className = \"thumb\"; img.alt = \"\"; img.loading = \"lazy\"; if (r.thumb) img.src = r.thumb;\n    const t = document.createElement(\"div\");\n    const n = cell(\"div\", r.name, \"rname\");\n    const sub = document.createElement(\"div\"); sub.className = \"sub\";\n    sub.append(cell(\"span\", LABEL[r.status] || \"Off\", \"chip \" + (r.status || \"OFF\")), document.createTextNode(r.adset + \" · \"));\n    if (r.preview) { const a = document.createElement(\"a\"); a.href = r.preview; a.target = \"_blank\"; a.rel = \"noopener\"; a.textContent = \"Preview ↗\"; sub.append(a); }\n    t.append(n, sub); box.append(img, t); td.append(box);\n  } else if (kind === \"campaign\" || kind === \"adset\") {   // click to drill down, like Ads Manager\n    const b = cell(\"button\", r.name, \"drill\"); b.type = \"button\"; b.title = kind === \"campaign\" ? \"View its ad sets\" : \"View its ads\";\n    b.addEventListener(\"click\", () => { drilled = true; $(kind).value = r.name; setLevel(kind === \"campaign\" ? \"adset\" : \"ad\"); });\n    td.append(b); if (r.sub) td.append(cell(\"div\", r.sub, \"sub\"));\n  } else if (kind === \"hook\") {   // click a batch or a hook to see its ads, with thumbnails and Preview\n    const b = cell(\"button\", r.name, \"drill\"); b.type = \"button\"; b.title = \"View these ads\";\n    b.addEventListener(\"click\", () => { drilled = true; pick = { ids: r._ids }; setLevel(\"ad\"); });\n    td.append(b); if (r.sub) td.append(cell(\"div\", r.sub, \"sub\"));\n  } else { td.append(cell(\"div\", r.name, \"rname\")); if (r.sub) td.append(cell(\"div\", r.sub, \"sub\")); }\n  return td;\n}\nfunction rowEl(r, kind, cls) {\n  const tr = document.createElement(\"tr\"); if (cls) tr.className = cls;\n  tr.append(nameCell(r, kind));\n  for (const [k, , f] of visible()) tr.append(cell(\"td\", fmt[f](r[k])));\n  return tr;\n}\n// Breakdown rows under a row: the selected breakdown's slices, summed over the row's ads.\nfunction slices(ids) {\n  if (!bd) return [];\n  const set = new Set(ids), m = new Map();\n  for (const s of bd.rows) if (set.has(s.ad)) { if (!m.has(s.key)) m.set(s.key, []); m.get(s.key).push(s); }\n  return [...m].map(([k, rs]) => sum(rs, { name: k })).sort(bySort);\n}\nfunction append(body, r, kind, cls) {\n  body.append(rowEl(r, kind, cls));\n  if (bd && kind !== \"slice\") for (const s of slices(r._ids || [r.id])) body.append(rowEl(s, \"slice\", \"slice\"));\n}\nconst money = (v) => v == null ? \"\" : \"$\" + v.toLocaleString(\"en-US\", { maximumFractionDigits: 0 });\nfunction group(rows, key, sub) {\n  const m = new Map();\n  for (const r of rows) { const k = key(r); if (!m.has(k)) m.set(k, []); m.get(k).push(r); }\n  return [...m].map(([k, rs]) => ({ ...sum(rs, { name: k, sub: sub ? sub(rs, k) : \"\" }), _ids: rs.map((x) => x.id) }));\n}\nfunction setLevel(l) {\n  level = l; document.querySelectorAll(\".tabs button\").forEach((x) => x.setAttribute(\"aria-selected\", String(x.dataset.level === l))); render();\n}\n// Owner tools (Strategist filter, Export CSV) show only for admin links, and hide while previewing as a strategist.\nfunction applyRole() {\n  const owner = !!(data && data.admin) && !viewerPreview;\n  $(\"asViewer\").hidden = !(data && data.admin);\n  $(\"access\").hidden = !owner; if (data && data.access) $(\"access\").href = data.access;   // invite / remove strategists\n  $(\"csL\").hidden = !owner; $(\"export\").hidden = !owner; $(\"previewNote\").hidden = !viewerPreview;\n  $(\"colsL\").hidden = !owner; $(\"colsBtn\").parentElement.hidden = !owner;   // strategists get the owner's columns\n  if (!owner && $(\"cs\").value) { $(\"cs\").value = \"\"; render(); }\n}\nfunction exportCsv() {\n  if (!data || !data.admin || viewerPreview) return;   // owner only\n  const rows = [...$(\"body\").querySelectorAll(\"tr\")].map((tr) => [...tr.children].map((td) => td.querySelector(\".rname, .drill\")?.textContent ?? td.textContent));\n  const head = [...$(\"head\").children].map((th) => th.textContent.replace(/ [▲▼]$/, \"\"));\n  const csv = [head, ...rows].map((r) => r.map((v) => `\"${String(v).replace(/\"/g, '\"\"').trim()}\"`).join(\",\")).join(\"\\n\");\n  const a = document.createElement(\"a\"); a.href = URL.createObjectURL(new Blob([csv], { type: \"text/csv\" }));\n  a.download = `auvra-ads-${level}-${$(\"preset\").value}.csv`; a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 1000);\n}\nconst bySort = (a, b) => { const x = sort.key === \"name\" ? a.name : a[sort.key], y = sort.key === \"name\" ? b.name : b[sort.key];\n  if (x == null && y == null) return 0; if (x == null) return 1; if (y == null) return -1; return (x > y ? 1 : x < y ? -1 : 0) * sort.dir; };\nfunction render() {\n  const head = $(\"head\"); head.replaceChildren();\n  const names = { ad: \"Ad name\", adset: \"Ad set\", campaign: \"Campaign\", hook: \"Batch / hook\" };\n  const hs = [[\"name\", names[level]], ...visible().map(([k, l]) => [k, l])];\n  for (const [k, l] of hs) { const th = cell(\"th\", l, k === \"name\" ? \"name\" : \"\"); th.dataset.key = k;\n    th.setAttribute(\"aria-sort\", sort.key === k ? (sort.dir > 0 ? \"ascending\" : \"descending\") : \"none\"); head.append(th); }\n  const body = $(\"body\"); body.replaceChildren();\n  if (!data) return;\n  const rows = filtered().map(derive);\n  if (!rows.length) { const tr = document.createElement(\"tr\"); const td = cell(\"td\", \"No ads match these filters.\", \"msg\"); td.colSpan = hs.length; tr.append(td); body.append(tr); return; }\n  const total = sum(rows, { name: `Results from ${rows.length} ads` });\n  append(body, { ...total, _ids: rows.map((r) => r.id) }, \"total\", \"total\");\n  const B = data.budgets || { campaigns: {}, adsets: {} };\n  if (level === \"ad\") rows.sort(bySort).forEach((r) => append(body, r, \"ad\"));\n  if (level === \"adset\") group(rows, (r) => r.adset, (rs, k) => { const b = B.adsets[k] || {};\n      return [rs[0].campaign, b.daily ? `Budget ${money(b.daily)}/day` : \"\", b.min ? `Min spend ${money(b.min)}/day` : \"\", `${rs.length} ads`].filter(Boolean).join(\" · \"); })\n    .sort(bySort).forEach((r) => append(body, r, \"adset\"));\n  if (level === \"campaign\") group(rows, (r) => r.campaign, (rs, k) => { const b = B.campaigns[k] || {};\n      return [b.daily ? `Budget ${money(b.daily)}/day` : b.lifetime ? `Lifetime budget ${money(b.lifetime)}` : \"\", `${new Set(rs.map((x) => x.adset)).size} ad sets · ${rs.length} ads`].filter(Boolean).join(\" · \"); })\n    .sort(bySort).forEach((r) => append(body, r, \"campaign\"));\n  if (level === \"hook\") {\n    const batch = (r) => r.name.replace(/H\\d+(?:-H\\d+)*(?=_)/, \"\").replace(/#/g, \"\");\n    const hooked = rows.filter((r) => /BATCH\\d*#?H\\d+|_B\\d+H\\d+/i.test(r.name));   // only ads named with the CS_BATCH#H# convention\n    if (!hooked.length) { const tr = document.createElement(\"tr\"); const td = cell(\"td\", \"No ads in this view use the CS_BATCH#H1/H2/H3 naming yet.\", \"msg\"); td.colSpan = hs.length; tr.append(td); body.append(tr); return; }\n    const batches = group(hooked, batch, (rs) => `${rs.length} hook ads`).sort(bySort);\n    for (const b of batches) {\n      body.append(rowEl(b, \"hook\", \"group\"));\n      const hooks = hooked.filter((r) => batch(r) === b.name);\n      group(hooks, (r) => (r.name.match(/H(\\d+(?:-H\\d+)*)(?=_)/) || [, \"—\"])[1].replace(/^/, \"H\").replace(/-H/g, \"+H\"), (rs) => rs.map((x) => LABEL[x.status] || \"Off\").join(\", \"))\n        .sort(bySort).forEach((h) => body.append(rowEl(h, \"hook\")));\n    }\n  }\n}\nfunction colMenu() {\n  const m = $(\"colmenu\"); m.replaceChildren();\n  for (const [k, l] of allCols()) { const lab = document.createElement(\"label\"); const cb = document.createElement(\"input\"); cb.type = \"checkbox\"; cb.checked = shown.includes(k); cb.id = \"col-\" + k;\n    cb.addEventListener(\"change\", () => { shown = cb.checked ? [...shown, k] : shown.filter((x) => x !== k);   // new columns go at the end, in the order ticked\n      preset = \"custom\"; $(\"preset-cols\").value = \"custom\"; saveLayout(); render(); });\n    lab.append(cb, document.createTextNode(l)); m.append(lab); }\n}\n// The owner's columns are the team's columns: saved to the server and loaded by every strategist.\nlet saveTimer = null;\nfunction saveLayout() {\n  try { localStorage.setItem(\"mirror-cols\", JSON.stringify(shown)); localStorage.setItem(\"mirror-preset\", preset); } catch {}\n  if (!data || !data.admin || viewerPreview) return;\n  clearTimeout(saveTimer);\n  saveTimer = setTimeout(() => fetch(location.pathname.replace(/\\/$/, \"\") + \"/layout\", { method: \"POST\", headers: { \"content-type\": \"application/json\" },\n    body: JSON.stringify({ preset, columns: shown }) }).then(() => { $(\"updated\").textContent = \"Team columns saved\"; }), 600);\n}\nlet layoutApplied = false;\nfunction applyLayout() {\n  if (layoutApplied || !data || !data.layout) return;\n  layoutApplied = true; shown = data.layout.columns; preset = data.layout.preset || \"custom\"; $(\"preset-cols\").value = preset;\n}\nasync function load(force) {\n  const p = $(\"preset\").value, qs = new URLSearchParams(p === \"custom\" ? { since: $(\"since\").value, until: $(\"until\").value } : { preset: p });\n  if (p === \"custom\" && (!$(\"since\").value || !$(\"until\").value)) return;\n  $(\"dot\").className = \"dot stale\"; $(\"updated\").textContent = \"Updating…\";\n  try {\n    const r = await fetch(location.pathname.replace(/\\/$/, \"\") + \"/data?\" + qs + (force ? \"&t=\" + Date.now() : \"\"), { cache: \"no-store\" });\n    const j = await r.json(); if (j.error) throw new Error(j.error);\n    data = j; for (const row of data.rows) row._cs = ownerOf(row);\n    applyLayout(); applyRole(); colMenu();\n    fillSelect(\"cs\", [...Object.keys(data.strategists || {}), \"Other\"]); fillSelect(\"campaign\", data.rows.map((r) => r.campaign)); fillSelect(\"adset\", data.rows.map((r) => r.adset));\n    $(\"dot\").className = \"dot\"; $(\"updated\").textContent = \"Live · updated \" + new Date(j.fetched).toLocaleTimeString([], { hour: \"numeric\", minute: \"2-digit\" });\n    await loadBreakdown(qs);\n    render();\n  } catch (e) { $(\"dot\").className = \"dot err\"; $(\"updated\").textContent = String(e.message || e); }\n}\nasync function loadBreakdown(qs) {\n  const by = $(\"breakdown\").value; if (!by) { bd = null; return; }\n  qs = qs || new URLSearchParams($(\"preset\").value === \"custom\" ? { since: $(\"since\").value, until: $(\"until\").value } : { preset: $(\"preset\").value });\n  const j = await (await fetch(location.pathname.replace(/\\/$/, \"\") + \"/data?\" + qs + \"&breakdown=\" + by, { cache: \"no-store\" })).json();\n  if (j.error) throw new Error(j.error);\n  bd = j;\n}\n$(\"head\").addEventListener(\"click\", (e) => { const th = e.target.closest(\"th\"); if (!th) return; const k = th.dataset.key;\n  sort = { key: k, dir: sort.key === k ? -sort.dir : (k === \"name\" ? 1 : -1) }; render(); });\ndocument.querySelector(\".tabs\").addEventListener(\"click\", (e) => { const b = e.target.closest(\"button\"); if (!b) return; level = b.dataset.level;\n  if (drilled) { drilled = false; pick = null; $(\"campaign\").value = \"\"; $(\"adset\").value = \"\"; }   // tabs go back to the full list after a click-through\n  document.querySelectorAll(\".tabs button\").forEach((x) => x.setAttribute(\"aria-selected\", String(x === b))); render(); });\n$(\"preset\").addEventListener(\"change\", () => { const c = $(\"preset\").value === \"custom\"; $(\"sinceL\").hidden = !c; $(\"untilL\").hidden = !c; if (!c) load(); });\nfor (const id of [\"since\", \"until\"]) $(id).addEventListener(\"change\", () => load());\n// Touching a filter yourself ends a click-through: no hidden hook filter, and tabs keep your choice.\nconst manual = () => { drilled = false; pick = null; render(); };\nfor (const id of [\"cs\", \"campaign\", \"adset\", \"status\"]) $(id).addEventListener(\"change\", manual);\n$(\"q\").addEventListener(\"input\", manual);\n$(\"refresh\").addEventListener(\"click\", () => load(true));\n$(\"preset-cols\").value = preset;\n$(\"preset-cols\").addEventListener(\"change\", () => { preset = $(\"preset-cols\").value;\n  if (preset !== \"custom\") shown = PRESET_COLS[preset];\n  saveLayout(); colMenu(); render(); });\n$(\"breakdown\").addEventListener(\"change\", async () => { $(\"updated\").textContent = \"Loading breakdown…\";\n  try { await loadBreakdown(); $(\"updated\").textContent = \"Live · breakdown loaded\"; } catch (e) { $(\"updated\").textContent = String(e.message || e); } render(); });\n$(\"export\").addEventListener(\"click\", exportCsv);\n$(\"asViewer\").addEventListener(\"click\", () => { viewerPreview = !viewerPreview;\n  $(\"asViewer\").setAttribute(\"aria-pressed\", String(viewerPreview)); $(\"asViewer\").textContent = viewerPreview ? \"Back to owner view\" : \"View as strategist\";\n  applyRole(); });\n$(\"colsBtn\").addEventListener(\"click\", () => { const m = $(\"colmenu\"); m.hidden = !m.hidden; $(\"colsBtn\").setAttribute(\"aria-expanded\", String(!m.hidden)); });\ndocument.addEventListener(\"click\", (e) => { if (!e.target.closest(\".cols\")) $(\"colmenu\").hidden = true; });\ncolMenu(); render(); load();\ntimer = setInterval(() => { if (!document.hidden) load(); }, 120000);\ndocument.addEventListener(\"visibilitychange\", () => { if (!document.hidden) load(); });\n</script></body></html>\n";
export const ADMIN_PAGE = "<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Ads Mirror Access</title>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Inter+Tight:wght@400;500;600;700&display=swap\">\n<style>\n  /* Owner's access list: invite on top, then who has a link, each with Copy and Remove. */\n  :root { --bg:#f4f5f7; --panel:#fff; --ink:#1c1e21; --muted:#65676b; --line:#e4e6eb; --accent:#1660d6; --bad:#c2282f; --ok:#1b8a4b; --sans:\"Inter Tight\",system-ui,sans-serif; }\n  @media (prefers-color-scheme: dark) { :root { --bg:#0f1115; --panel:#181b21; --ink:#e7e9ee; --muted:#9aa1ad; --line:#2a2f38; --accent:#5c9bff; --bad:#ff6b6b; --ok:#4cc38a; color-scheme:dark; } }\n  * { box-sizing:border-box; }\n  [hidden] { display:none !important; }\n  body { margin:0; background:var(--bg); color:var(--ink); font:15px/1.5 var(--sans); }\n  main { max-width:820px; margin:0 auto; padding:24px max(16px, env(safe-area-inset-left)) 48px max(16px, env(safe-area-inset-right)); display:grid; gap:16px; }\n  h1 { margin:0; font-size:22px; } p { margin:0; color:var(--muted); }\n  .card { background:var(--panel); border:1px solid var(--line); border-radius:10px; padding:16px; display:grid; gap:12px; }\n  form { display:flex; gap:8px; flex-wrap:wrap; }\n  input { flex:1 1 220px; font:inherit; padding:8px 10px; border:1px solid var(--line); border-radius:6px; background:var(--panel); color:var(--ink); }\n  button { font:inherit; font-weight:600; border:1px solid var(--line); background:var(--panel); color:var(--ink); border-radius:6px; padding:8px 14px; cursor:pointer; }\n  button.primary { background:var(--accent); border-color:var(--accent); color:#fff; }\n  button.danger { color:var(--bad); }\n  .new { border:1px solid var(--ok); border-radius:8px; padding:10px 12px; display:grid; gap:6px; }\n  .new code, td code { font-size:12px; overflow-wrap:anywhere; }\n  table { width:100%; border-collapse:collapse; }\n  th, td { text-align:left; padding:10px 6px; border-bottom:1px solid var(--line); vertical-align:middle; }\n  th { font-size:12px; color:var(--muted); font-weight:600; }\n  td.act { white-space:nowrap; text-align:right; }\n  .empty { color:var(--muted); padding:12px 6px; }\n  :focus-visible { outline:2px solid var(--accent); outline-offset:1px; }\n  .tag { font-size:12px; color:var(--muted); }\n</style></head>\n<body><main>\n  <h1>Ads Mirror access</h1>\n  <p>Approve someone from Slack with <b>/cs-addtoreport @person</b> (only you can run it): they get their own link to the live Ads Mirror (all ads, read-only) by DM. Or invite by name here and send the link yourself. Remove access and their link stops working immediately. Every invite, removal and visit is in your bot audit log.</p>\n  <section class=\"card\">\n    <form id=\"f\"><input id=\"name\" placeholder=\"Name, e.g. Pedro Alvite\" aria-label=\"Name\" autocomplete=\"off\"><button class=\"primary\" type=\"submit\">Invite</button></form>\n    <div class=\"new\" id=\"new\" hidden><b id=\"newWho\"></b><code id=\"newLink\"></code><div><button type=\"button\" id=\"copyNew\">Copy link</button></div></div>\n  </section>\n  <section class=\"card\">\n    <table><thead><tr><th>Person</th><th>Invited</th><th>Link</th><th></th></tr></thead><tbody id=\"list\"><tr><td class=\"empty\" colspan=\"4\">Loading…</td></tr></tbody></table>\n  </section>\n</main>\n<script>\nconst base = location.pathname.replace(/\\/$/, \"\");\nconst copy = async (text, btn) => { try { await navigator.clipboard.writeText(text); btn.textContent = \"Copied\"; } catch { btn.textContent = \"Select the link to copy\"; } setTimeout(() => btn.textContent = btn.dataset.label || \"Copy link\", 1500); };\nasync function list() {\n  const rows = await (await fetch(base + \"/list\", { cache: \"no-store\" })).json();\n  const tb = document.getElementById(\"list\"); tb.replaceChildren();\n  if (!rows.length) { const tr = document.createElement(\"tr\"); const td = document.createElement(\"td\"); td.className = \"empty\"; td.colSpan = 4; td.textContent = \"Nobody has access yet.\"; tr.append(td); tb.append(tr); return; }\n  for (const r of rows) {\n    const tr = document.createElement(\"tr\");\n    const n = document.createElement(\"td\"); n.textContent = r.name;\n    if (r.slack) n.append(document.createElement(\"br\"), Object.assign(document.createElement(\"span\"), { className: \"tag\", textContent: \"Approved in Slack · link sent by DM\" }));\n    const d = document.createElement(\"td\"); d.textContent = new Date(r.invited).toLocaleDateString([], { month: \"short\", day: \"numeric\", year: \"numeric\" });\n    const l = document.createElement(\"td\"); const c = document.createElement(\"code\"); c.textContent = r.link; l.append(c);\n    const a = document.createElement(\"td\"); a.className = \"act\";\n    const cp = document.createElement(\"button\"); cp.type = \"button\"; cp.textContent = \"Copy link\"; cp.onclick = () => copy(r.link, cp);\n    const rm = document.createElement(\"button\"); rm.type = \"button\"; rm.className = \"danger\"; rm.textContent = \"Remove access\";\n    rm.onclick = async () => {\n      if (rm.dataset.armed !== \"1\") { rm.dataset.armed = \"1\"; rm.textContent = \"Click again to remove\"; setTimeout(() => { rm.dataset.armed = \"\"; rm.textContent = \"Remove access\"; }, 3000); return; }\n      await fetch(base + \"/revoke\", { method: \"POST\", headers: { \"content-type\": \"application/json\" }, body: JSON.stringify({ token: r.token }) }); list();\n    };\n    a.append(cp, document.createTextNode(\" \"), rm); tr.append(n, d, l, a); tb.append(tr);\n  }\n}\ndocument.getElementById(\"f\").addEventListener(\"submit\", async (e) => {\n  e.preventDefault(); const name = document.getElementById(\"name\").value.trim(); if (!name) return;\n  const r = await (await fetch(base + \"/invite\", { method: \"POST\", headers: { \"content-type\": \"application/json\" }, body: JSON.stringify({ name }) })).json();\n  if (r.error) return alertBox(r.error);\n  document.getElementById(\"new\").hidden = false; document.getElementById(\"newWho\").textContent = \"Access created for \" + r.name + \". Send them this link:\";\n  document.getElementById(\"newLink\").textContent = r.link; document.getElementById(\"copyNew\").onclick = (ev) => copy(r.link, ev.target);\n  document.getElementById(\"name\").value = \"\"; list();\n});\nfunction alertBox(t) { const n = document.getElementById(\"new\"); n.hidden = false; document.getElementById(\"newWho\").textContent = t; document.getElementById(\"newLink\").textContent = \"\"; }\nlist();\n</script></body></html>\n";
